contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 k) public {
        require(k > 0 && k <= 1000 * 10**18);
        // acquire a 1000e18 airdrop balance as owner (this contract deployed c)
        c.getTokens(); if (__ESBMC_reverted()) return;
        uint256 balBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 distrBefore = c.totalDistributed(); if (__ESBMC_reverted()) return;
        c.burn(k); if (__ESBMC_reverted()) return;
        assert(
            c.balanceOf(address(this)) == balBefore - k &&
            c.totalSupply() == supplyBefore - k &&
            c.totalDistributed() == distrBefore - k
        );
    }
    receive() external payable {}
}

